import fs from "fs";
import path from "path";
import postcss from "postcss";

const root = path.join(import.meta.dirname, "..");
const srcPath = path.join(root, "styles", "subtrack.css");
const lines = fs.readFileSync(srcPath, "utf8").split(/\r?\n/);

const GENERATED_BANNER =
  "/* Generated by scripts/split-landing-css.mjs – nerediģēt; labo styles/subtrack.css, tad npm run css:split */\n";

function indexOfMarker(text, fromIndex = 0) {
  const i = lines.findIndex(
    (line, idx) => idx >= fromIndex && line.includes(text),
  );
  if (i === -1) {
    throw new Error(
      `css:split: nav atrasts marķieris "${text}" styles/subtrack.css. Atjaunini scripts/split-landing-css.mjs.`,
    );
  }
  return i;
}

function sectionBannerStart(markerText, fromIndex = 0) {
  const subtitleIdx = indexOfMarker(markerText, fromIndex);
  const prev = lines[subtitleIdx - 1] ?? "";
  if (prev.includes("====")) return subtitleIdx - 1;
  return subtitleIdx;
}

/** 1-based: rindas start..endInclusive */
function sliceRange(start1, end1Inclusive) {
  if (end1Inclusive < start1) {
    throw new Error(
      `css:split: tukšs griezums ${start1}–${end1Inclusive} (pārbaudi marķierus).`,
    );
  }
  return lines.slice(start1 - 1, end1Inclusive).join("\n") + "\n";
}

const idxLandingPage = sectionBannerStart("Landing page");
const idxDemo = indexOfMarker("Publiskās /demo/* lapas");
const idxLandingStack = indexOfMarker(".landing-stack {");
const idxDashboardLayout = sectionBannerStart("Dashboard layout (augšējā navigācija)");
const idxDashboardCalendar = sectionBannerStart(
  "Dashboard: kalendārs kreisajā kolonnā",
);
const idxModal = sectionBannerStart("Modal");
const idxMobileNav = sectionBannerStart("Mobila apakšējā navigācija");
const idxSubscribe = sectionBannerStart("/subscribe Pro lapa");
const idxLegal = sectionBannerStart("Legal pages, footer links, cookie consent");
const idxAdminEmail = indexOfMarker("Admin – e-pasta dizains");

let idxLandingFooter = -1;
for (let i = idxLandingStack; i < idxDashboardLayout; i++) {
  if (lines[i].startsWith(".landing-footer {")) idxLandingFooter = i;
}
if (idxLandingFooter === -1) {
  throw new Error("css:split: nav atrasts .landing-footer { pirms Dashboard layout.");
}

const modulesDir = path.join(root, "styles", "modules");
fs.mkdirSync(modulesDir, { recursive: true });

const corePath = path.join(modulesDir, "core.css");
const landingPagePath = path.join(modulesDir, "landing-page.css");
const sharedFooterPath = path.join(modulesDir, "shared-footer.css");
const landingShellPath = path.join(modulesDir, "landing-shell.css");
const mockPanelPath = path.join(modulesDir, "landing-mock-panel.css");
const demoAppPath = path.join(modulesDir, "demo-app.css");
const subtrackAppPanelPath = path.join(modulesDir, "subtrack-app-panel.css");
const subtrackAppDeferredPath = path.join(modulesDir, "subtrack-app-deferred.css");
const subtrackAppShellNavPath = path.join(modulesDir, "subtrack-app-shell-nav.css");
const subtrackAppTailPath = path.join(modulesDir, "subtrack-app-tail.css");
const subtrackAppPath = path.join(modulesDir, "subtrack-app.css");

fs.writeFileSync(corePath, sliceRange(1, idxLandingPage));

fs.writeFileSync(
  landingPagePath,
  sliceRange(idxLandingPage + 1, idxDemo) +
    sliceRange(idxLandingStack + 1, idxLandingFooter - 1),
);

fs.writeFileSync(
  sharedFooterPath,
  sliceRange(idxLandingFooter + 1, idxDashboardLayout),
);

let shell =
  "/* Landing shell: topbar, lang switcher, mobile nav, footer, cookies */\n";
shell += sliceRange(idxDashboardLayout + 1, idxDashboardCalendar);
shell += sliceRange(idxMobileNav + 1, idxSubscribe);
shell += sliceRange(idxLegal + 1, idxAdminEmail);
fs.writeFileSync(landingShellPath, shell);

fs.writeFileSync(
  mockPanelPath,
  "/* Landing hero mock: pay-calendar, stat cards, sub-list (bāze no paneļa) */\n" +
    sliceRange(idxDashboardCalendar + 1, idxModal),
);

fs.writeFileSync(
  demoAppPath,
  "/* /demo/* routes: banner, topbar badge, analytics donut */\n" +
    sliceRange(idxDemo + 1, idxLandingStack),
);

fs.writeFileSync(
  subtrackAppPanelPath,
  "/* Panelis / analītika: layout, kalendārs, stats, saraksts (pirms Modal) */\n" +
    sliceRange(idxDashboardLayout + 1, idxModal - 1),
);

fs.writeFileSync(
  subtrackAppDeferredPath,
  "/* Atlikts: modāļi, toast, admin, e-pasts dizains */\n" +
    sliceRange(idxModal, idxMobileNav - 1),
);

fs.writeFileSync(
  subtrackAppShellNavPath,
  "/* Apakšējā navigācija (panelis, admin mobilā) */\n" +
    sliceRange(idxMobileNav, idxSubscribe - 1),
);

fs.writeFileSync(
  subtrackAppTailPath,
  "/* Subscribe, legal, cookie, pārējais app */\n" +
    sliceRange(idxSubscribe, lines.length),
);

fs.writeFileSync(
  subtrackAppPath,
  "/* App UI: dashboard, admin, auth, panel (kopā) */\n" +
    [
      fs.readFileSync(subtrackAppPanelPath, "utf8"),
      fs.readFileSync(subtrackAppDeferredPath, "utf8"),
      fs.readFileSync(subtrackAppShellNavPath, "utf8"),
      fs.readFileSync(subtrackAppTailPath, "utf8"),
    ].join(""),
);

function writeFlatBundle(outPath, partPaths) {
  const body = partPaths
    .map((p) => fs.readFileSync(p, "utf8").trimEnd())
    .join("\n\n");
  fs.writeFileSync(outPath, `${GENERATED_BANNER}\n${body}\n`);
}

const landingOut = path.join(root, "styles", "landing.css");
const appBundleOut = path.join(root, "styles", "subtrack-app.bundle.css");
const appCriticalOut = path.join(root, "styles", "subtrack-app-critical.bundle.css");
const appDeferredOut = path.join(root, "styles", "subtrack-app-deferred.bundle.css");
const publicStylesDir = path.join(root, "public", "styles");

writeFlatBundle(landingOut, [
  corePath,
  landingPagePath,
  mockPanelPath,
  sharedFooterPath,
  landingShellPath,
]);

writeFlatBundle(appBundleOut, [corePath, sharedFooterPath, demoAppPath, subtrackAppPath]);

writeFlatBundle(appCriticalOut, [
  corePath,
  sharedFooterPath,
  subtrackAppPanelPath,
  subtrackAppShellNavPath,
]);

writeFlatBundle(appDeferredOut, [
  demoAppPath,
  subtrackAppDeferredPath,
  subtrackAppTailPath,
]);

fs.mkdirSync(publicStylesDir, { recursive: true });
fs.copyFileSync(appDeferredOut, path.join(publicStylesDir, "subtrack-app-deferred.bundle.css"));

function assertValidCss(filePath) {
  const css = fs.readFileSync(filePath, "utf8");
  try {
    postcss.parse(css, { from: filePath });
  } catch (e) {
    throw new Error(
      `${path.relative(root, filePath)}: ${e.message}\n` +
        "Labo styles/subtrack.css un/vai scripts/split-landing-css.mjs.",
    );
  }
}

for (const f of [landingOut, appBundleOut, appCriticalOut, appDeferredOut]) {
  assertValidCss(f);
}

for (const f of [
  "styles/subtrack.css",
  "styles/landing.css",
  "styles/subtrack-app.bundle.css",
  "styles/subtrack-app-critical.bundle.css",
  "styles/subtrack-app-deferred.bundle.css",
]) {
  const kb = (fs.statSync(path.join(root, f)).size / 1024).toFixed(1);
  console.log(`${f}: ${kb} KB`);
}

console.log("css:split OK (PostCSS sintakse pārbaudīta)");
